function PouringLadleSkimmerSieveMaker.init() PouringLadleSkimmerSieveMaker.ironStock=12; PouringLadleSkimmerSieveMaker.bronzeStock=10; PouringLadleSkimmerSieveMaker.woodStock=14; PouringLadleSkimmerSieveMaker.leatherStock=10; PouringLadleSkimmerSieveMaker.silverStock=8; PouringLadleSkimmerSieveMaker.goldStock=6; PouringLadleSkimmerSieveMaker.jewelStock=4; PouringLadleSkimmerSieveMaker.pearlStock=4; PouringLadleSkimmerSieveMaker.productStock={}; PouringLadleSkimmerSieveMaker.buildings={}; PouringLadleSkimmerSieveMaker.maker=nil; PouringLadleSkimmerSieveMaker.activeMaking={}; PouringLadleSkimmerSieveMaker.totalProducts=0; PouringLadleSkimmerSieveMaker.dayTimer=0; print("[PouringLadleSkimmerSieveMaker] Royal Pouring Ladle Skimmer Sieve Maker System initialized (6 products, 4 buildings)") end
function PouringLadleSkimmerSieveMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PouringLadleSkimmerSieveMaker.maker={name=n or ("Sitnikar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sitnikar najet: %s (spretnost: %d)",PouringLadleSkimmerSieveMaker.maker.name,s),"success") end; return true end
function PouringLadleSkimmerSieveMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PouringLadleSkimmerSieveMaker.build(id) local ok,e=PouringLadleSkimmerSieveMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PouringLadleSkimmerSieveMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
