function PouringLadleSkimmerSieveMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and PouringLadleSkimmerSieveMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and PouringLadleSkimmerSieveMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and PouringLadleSkimmerSieveMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and PouringLadleSkimmerSieveMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and PouringLadleSkimmerSieveMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PouringLadleSkimmerSieveMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PouringLadleSkimmerSieveMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PouringLadleSkimmerSieveMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PouringLadleSkimmerSieveMaker.buildings==0 then return false,"Potrebna sitnična delavnica" end; if not PouringLadleSkimmerSieveMaker.maker then return false,"Potreben sitnikar" end; return true end
function PouringLadleSkimmerSieveMaker.make(pt,qty) qty=qty or 1; local ok,e=PouringLadleSkimmerSieveMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then PouringLadleSkimmerSieveMaker.ironStock=PouringLadleSkimmerSieveMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then PouringLadleSkimmerSieveMaker.bronzeStock=PouringLadleSkimmerSieveMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then PouringLadleSkimmerSieveMaker.woodStock=PouringLadleSkimmerSieveMaker.woodStock-d.woodCost*qty end; if d.leatherCost then PouringLadleSkimmerSieveMaker.leatherStock=PouringLadleSkimmerSieveMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then PouringLadleSkimmerSieveMaker.silverStock=PouringLadleSkimmerSieveMaker.silverStock-d.silverCost*qty end; if d.goldCost then PouringLadleSkimmerSieveMaker.goldStock=PouringLadleSkimmerSieveMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PouringLadleSkimmerSieveMaker.jewelStock=PouringLadleSkimmerSieveMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PouringLadleSkimmerSieveMaker.pearlStock=PouringLadleSkimmerSieveMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PouringLadleSkimmerSieveMaker.maker then t=math.max(1,t-math.floor(PouringLadleSkimmerSieveMaker.maker.skill/13)) end; table.insert(PouringLadleSkimmerSieveMaker.activeMaking,{id="pouringladleskimmersieve_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PouringLadleSkimmerSieveMaker.completeMaking(m) local q=1.0+(PouringLadleSkimmerSieveMaker.getQualityBonus()/100); if PouringLadleSkimmerSieveMaker.maker then q=q+(PouringLadleSkimmerSieveMaker.maker.skill/140) end; q=math.min(2.5,q); PouringLadleSkimmerSieveMaker.productStock[m.productType]=(PouringLadleSkimmerSieveMaker.productStock[m.productType] or 0)+m.quantity; PouringLadleSkimmerSieveMaker.totalProducts=PouringLadleSkimmerSieveMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PouringLadleSkimmerSieveMaker.maker then PouringLadleSkimmerSieveMaker.maker.itemsMade=PouringLadleSkimmerSieveMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PouringLadleSkimmerSieveMaker.maker.skill=math.min(100,PouringLadleSkimmerSieveMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sito izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"pouringladleskimmersieve.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function PouringLadleSkimmerSieveMaker.update(dt) if not _G.state then return end; PouringLadleSkimmerSieveMaker.dayTimer=PouringLadleSkimmerSieveMaker.dayTimer+dt; if PouringLadleSkimmerSieveMaker.dayTimer>=30 then PouringLadleSkimmerSieveMaker.dayTimer=0; for i=#PouringLadleSkimmerSieveMaker.activeMaking,1,-1 do local m=PouringLadleSkimmerSieveMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PouringLadleSkimmerSieveMaker.completeMaking(m); table.remove(PouringLadleSkimmerSieveMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PouringLadleSkimmerSieveMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PouringLadleSkimmerSieveMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
